import * as ImagePicker from "expo-image-picker";
import { useCallback, useEffect, useState } from "react";

import { analytics } from "@/config/analytics";
import { useRecording } from "@/services/audio";
import type { DraftSnapshot } from "@/services/drafts/snapshot";
import { downscaleImage, pickDocuments } from "@/services/media";
import type { Attachment, Entry } from "@/shared/types";
import { MAX_ATTACHMENTS, MAX_IMAGES } from "../types";

/**
 * Photos, voice notes, and kept documents attached to a compose draft, plus
 * the side effects that capture them (picker permissions, recorder lifecycle).
 * Isolated here so the screen's render loop stays free of media concerns.
 */
export function useMediaAttachments({
  existing,
  restored,
}: {
  existing: Entry | undefined;
  /** An unsaved draft to resume; wins over the stored entry. */
  restored: DraftSnapshot | null;
}) {
  const initial = restored ?? existing;
  const [images, setImages] = useState<string[]>(() => initial?.images ?? []);
  const [audios, setAudios] = useState<string[]>(() => initial?.audios ?? []);
  const [attachments, setAttachments] = useState<Attachment[]>(() => initial?.attachments ?? []);

  const {
    isRecording,
    durationMs: recordingDurationMs,
    liveLevels: recordingLevels,
    recordedUri,
    toggle,
    cancel,
    clear,
  } = useRecording();

  // Commit a finished take into the attachments list so the next recording
  // starts from a clean slate.
  useEffect(() => {
    if (!recordedUri || isRecording) return;
    setAudios((prev) => (prev.includes(recordedUri) ? prev : [...prev, recordedUri]));
    clear();
  }, [recordedUri, isRecording, clear]);

  const pickImage = useCallback(async () => {
    if (images.length >= MAX_IMAGES) return;

    const { granted } = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (!granted) return;

    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: "images",
      // Full quality here — downscaleImage performs the only re-encode.
      quality: 1,
      allowsMultipleSelection: true,
      selectionLimit: MAX_IMAGES - images.length,
    });
    if (!result.canceled) {
      // Shrink before state so the preview and the durable copy share one small file.
      const downscaled = await Promise.all(
        result.assets.map((asset) => downscaleImage(asset.uri, asset))
      );
      setImages((prev) => [...prev, ...downscaled]);
      analytics.capture("photo_attached", { photo_count: downscaled.length });
    }
  }, [images.length]);

  const pickAttachments = useCallback(async () => {
    if (attachments.length >= MAX_ATTACHMENTS) return;

    const picked = await pickDocuments(MAX_ATTACHMENTS - attachments.length);
    if (picked.length > 0) {
      setAttachments((prev) => [...prev, ...picked]);
      analytics.capture("file_attached", { file_count: picked.length });
    }
  }, [attachments.length]);

  const removeImage = useCallback((index: number) => {
    setImages((prev) => prev.filter((_, i) => i !== index));
  }, []);

  const removeAudio = useCallback((index: number) => {
    setAudios((prev) => prev.filter((_, i) => i !== index));
  }, []);

  const removeAttachment = useCallback((index: number) => {
    setAttachments((prev) => prev.filter((_, i) => i !== index));
  }, []);

  /** Discard edits and restore the media of `to`, by default the entry being edited. */
  const reset = useCallback(
    (to: Entry | undefined = existing) => {
      // Stop the mic and drop any in-progress or finished-but-unsaved take.
      void cancel();
      setImages(to?.images ?? []);
      setAudios(to?.audios ?? []);
      setAttachments(to?.attachments ?? []);
      clear();
    },
    [existing, cancel, clear]
  );

  return {
    images,
    audios,
    attachments,
    isRecording,
    recordingDurationMs,
    recordingLevels,
    pickImage,
    pickAttachments,
    removeImage,
    removeAudio,
    removeAttachment,
    toggleRecording: toggle,
    reset,
  };
}
import { useCallback, useRef, useState } from "react";
import { analytics } from "@/config/analytics";
import type { EntryLocation } from "@/shared/types";
import { fetchPlace } from "./location";

/**
 * Location attach state for the compose screen.
 *
 * `on` is the explicit user intent to attach location.
 * `place` is the resolved place data.
 * Location is strictly opt-in: no automatic fetching, no background tracking,
 * no refresh on typing. Fetches only occur when the user explicitly triggers an action.
 */
export function useLocation(initialLocation?: EntryLocation | null) {
  const [on, setOn] = useState(Boolean(initialLocation));
  const [place, setPlace] = useState<EntryLocation | null>(initialLocation ?? null);
  const [loading, setLoading] = useState(false);
  const [failed, setFailed] = useState(false);

  // Bumped on every fetch and on detach so stale responses are safely ignored.
  const fetchId = useRef(0);

  const fetchAndAttach = useCallback(
    async (options: { prompt: boolean; refresh?: boolean }) => {
      const id = ++fetchId.current;
      setLoading(true);
      setFailed(false);

      try {
        const loc = await fetchPlace(options);
        if (id !== fetchId.current) return;

        setLoading(false);
        if (loc) {
          setPlace(loc);
          setOn(true);
          setFailed(false);
          analytics.capture("location_used");
        } else {
          setFailed(true);
          if (!place) {
            setOn(false);
          }
        }
      } catch {
        if (id !== fetchId.current) return;
        setLoading(false);
        setFailed(true);
      }
    },
    [place]
  );

  const request = useCallback(async () => {
    await fetchAndAttach({ prompt: true });
  }, [fetchAndAttach]);

  const refresh = useCallback(async () => {
    await fetchAndAttach({ prompt: true, refresh: true });
  }, [fetchAndAttach]);

  const remove = useCallback(() => {
    fetchId.current += 1;
    setOn(false);
    setPlace(null);
    setFailed(false);
    setLoading(false);
  }, []);

  /** Restore the location the draft started with, or `to`, discarding edits. */
  const reset = useCallback(
    (to: EntryLocation | null | undefined = initialLocation) => {
      fetchId.current += 1;
      setOn(Boolean(to));
      setPlace(to ?? null);
      setLoading(false);
      setFailed(false);
    },
    [initialLocation]
  );

  const toggle = useCallback(async () => {
    if (loading) return;
    if (on) {
      remove();
    } else {
      await request();
    }
  }, [loading, on, remove, request]);

  return {
    on,
    place,
    loading,
    failed,
    request,
    refresh,
    remove,
    reset,
    toggle,
  };
}

import { Feather } from "@expo/vector-icons";
