type Props = NativeStackScreenProps<RootStackParamList, "Compose">;

/** The unsaved draft stored for `key`: `undefined` while reading, `null` when there is none. */
function useStoredDraft(key: string): DraftSnapshot | null | undefined {
  const [loaded, setLoaded] = useState<{ key: string; draft: DraftSnapshot | null }>();

  useEffect(() => {
    let active = true;
    loadDraft(key)
      .catch((error) => {
        reportError("compose:loadDraft", error);
        return null;
      })
      .then((draft) => {
        if (active) setLoaded({ key, draft });
      });
    return () => {
      active = false;
    };
  }, [key]);

  return loaded?.key === key ? loaded.draft : undefined;
}

export function ComposeScreen({ navigation, route }: Props) {
  const { colors } = useTheme().theme;
  const entryId = route.params?.entryId;
  const entry = useEntry(entryId);
  const storedDraft = useStoredDraft(entryId ?? NEW_ENTRY_DRAFT);

  // Editing an entry that no longer exists — leave.
  useEffect(() => {
    if (!entryId) return;
    if (entry === null) {
      // Entry was checked and doesn't exist
      const timer = setTimeout(() => {
        navigation.goBack();
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [entryId, entry, navigation]);

  if ((entryId && entry === undefined) || storedDraft === undefined) {
    return (
      <Layout.Screen style={[styles.screen, { backgroundColor: colors.background }]}>
        <ScreenHeader title={entryId ? "Entry" : "New entry"} onBack={() => navigation.goBack()} />
      </Layout.Screen>
    );
  }

  if (entryId && entry === null) {
    return (
      <Layout.Screen style={[styles.screen, { backgroundColor: colors.background }]}>
        <ScreenHeader title="Entry" onBack={() => navigation.goBack()} />
      </Layout.Screen>
    );
  }

  const composeKey =
    entry?.id ??
    ["new", route.params?.initialDate, route.params?.initialTagId]
      .filter((part) => part !== undefined)
      .join("-");

  return (
    <ComposeContent
      key={composeKey}
      navigation={navigation}
      route={route}
      existing={entry ?? undefined}
      restored={storedDraft}
    />
  );
}

interface ComposeContentProps {
  navigation: Props["navigation"];
  route: Props["route"];
  existing?: Entry;
  restored: DraftSnapshot | null;
}

function ComposeContent({ navigation, route, existing, restored }: ComposeContentProps) {
  const { colors } = useTheme().theme;
  const entryId = existing?.id;
  // An unsaved edit reopens where it was left.
  const [mode, setMode] = useState<"view" | "edit">(
    restored ? "edit" : (route.params?.mode ?? (entryId ? "view" : "edit"))
  );
  const isReadOnly = Boolean(entryId && mode === "view");
  const [datePickerOpen, setDatePickerOpen] = useState(false);
  const [timePickerOpen, setTimePickerOpen] = useState(false);
  const [detailsOpen, setDetailsOpen] = useState(false);
  const [tagsOpen, setTagsOpen] = useState(false);

  const { removeEntry } = useEntries();

  const inputRef = useRef<TextInput>(null);
  const keepFocus = useKeepFocus(inputRef);

  const media = useMediaAttachments({ existing, restored });
  const draft = useComposeDraft({
    existing,
    restored,
    media,
    initialDate: route.params?.initialDate,
    initialTagId: route.params?.initialTagId,
  });
  const { location } = draft;

  // Pre-focus the writing surface when entering compose or switching to edit mode
  useEffect(() => {
    if (!isReadOnly) {
      const timer = setTimeout(() => {
        inputRef.current?.focus();
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [isReadOnly]);

  const title = isReadOnly ? "Entry" : existing ? "Edit entry" : "New entry";

  // Opened from this tag's timeline: returning shows it again without stacking a copy.
  const openTag = (tagId: string) => {
    const { routes, index } = navigation.getState();
    const previous = routes[index - 1];
    const params = previous?.params;
    if (previous?.name === "Tag" && params && "tagId" in params && params.tagId === tagId) {
      navigation.goBack();
    } else {
      navigation.push("Tag", { tagId });
    }
  };

  const headerRight = isReadOnly ? (
    <View style={styles.headerActions}>
      <Pressable
        onPress={() => setMode("edit")}
        hitSlop={space.md}
        style={({ pressed }) => pressed && press}
        accessibilityRole="button"
        accessibilityLabel="Edit"
      >
        <Feather name="edit-2" size={metrics.iconMd} color={colors.text} />
      </Pressable>
      <Pressable
        onPress={() => setDetailsOpen(true)}
        hitSlop={space.md}
        style={({ pressed }) => pressed && press}
        accessibilityRole="button"
        accessibilityLabel="Entry details"
      >
        <Feather name="more-vertical" size={metrics.iconMd} color={colors.textSecondary} />
      </Pressable>
    </View>
  ) : existing ? (
    <Pressable
      onPress={() => {
        draft.reset();
        media.reset();
        setMode("view");
      }}
      hitSlop={space.md}
      style={({ pressed }) => pressed && press}
      accessibilityRole="button"
      accessibilityLabel="Cancel"
    >
      <Feather name="x" size={metrics.iconLg} color={colors.textSecondary} />
    </Pressable>
  ) : undefined;

  const handleSave = async () => {
    const outcome = await draft.save();
    const entryProperties = {
      has_text: draft.text.trim().length > 0,
      image_count: media.images.length,
      audio_count: media.audios.length,
      file_count: media.attachments.length,
      has_location: Boolean(location.on && location.place),
    };

    if (outcome === "created") {
      analytics.capture("entry_created", entryProperties);
      navigation.goBack();
    } else if (outcome === "updated") {
      analytics.capture("entry_updated", entryProperties);
      setMode("view");
    }
  };

  const handleLocationPress = async () => {
    await location.request();
    keepFocus();
  };

  const handleLocationRefresh = async () => {
    await location.refresh();
    keepFocus();
  };

  const handleLocationRemove = () => {
    location.remove();
    keepFocus();
  };

  return (
    <Layout.Screen style={[styles.screen, { backgroundColor: colors.background }]}>
      <ScreenHeader title={title} onBack={() => navigation.goBack()} right={headerRight} />

      <DateTimeBadges
        when={draft.when}
        onOpenDate={isReadOnly ? undefined : () => setDatePickerOpen(true)}
        onOpenTime={isReadOnly ? undefined : () => setTimePickerOpen(true)}
        location={location.place}
        locationOn={location.on}
        locationLoading={location.loading}
        locationFailed={location.failed}
        onLocationPress={isReadOnly ? undefined : handleLocationPress}
        onLocationRefresh={isReadOnly ? undefined : handleLocationRefresh}
        onLocationRemove={isReadOnly ? undefined : handleLocationRemove}
